/*
 * Erase First or Second Letter
 * 
 * Given a string 's' of length 'n', you can repeatedly perform one of two 
 * operations: delete the first character, or delete the second character. 
 * Calculate the total number of distinct non-empty strings that can be 
 * generated by performing these operations any number of times.
 * 
 * Constraints  :
 *                1 <= t <= 10^4 (number of test cases)
 *                1 <= n <= 10^5
 *                The sum of n over all test cases does not exceed 2 * 10^5.
 *                String 's' consists only of lowercase English letters.
 * 
 * Example 1    :
 * Input        : n = 4, s = "abac"
 * Output       : 8
 * Explanation  : The 8 distinct reachable strings are: "a", "b", "c", "ab", "ac", "bac", "aba", "abac".
 * 
 * Example 2    :
 * Input        : n = 5, s = "aaaaa"
 * Output       : 5
 * Explanation  : The 5 distinct reachable strings are: "a", "aa", "aaa", "aaaa", "aaaaa".
 *
 * https://codeforces.com/problemset/problem/1917/B
*/

// ! Observation

#include <iostream>
#include <unordered_set>
 
using namespace std;
typedef long long ll;

void solve() {
  int n;
  cin >> n;
  string s;
  cin >> s;
  ll ans = 0;
  unordered_set<char> st;
  // * Sum up the distinct counts for each position
  for (auto &c: s) {
    st.insert(c);
    ans += st.size();
  }
  cout << ans << "\n";
} 

// ! Counting Distinct Prefix
// * Time Complexity (TC): O(n) = O(2*10^5)
// * Space Complexity (SC): O(1) = O(1)
int main() {
  // Optimize standard I/O operations for competitive programming
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  
  int t;
  cin >> t;
  while (t--) {
    solve();
  }
	return 0;
}

